        }

        address ownerAfter = c.owner();

        assert(reverted ? ownerAfter == ownerBefore : ownerAfter == newOwner);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address firstNewOwner, address secondNewOwner) public {
        require(address(this) != firstNewOwner || firstNewOwner != address(0), "invalid first owner");

        bool revertedFirst;
        try c.transferOwnership(firstNewOwner) {
            revertedFirst = false;
        } catch {
            revertedFirst = true;
        }

        address ownerAfterFirst = c.owner();

        bool revertedSecond;
        try c.transferOwnership(secondNewOwner) {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        address ownerAfterSecond = c.owner();

        assert(
            (revertedFirst ? ownerAfterFirst == ownerAfterFirst : ownerAfterFirst == firstNewOwner) &&
            (revertedSecond ? ownerAfterSecond == ownerAfterFirst : ownerAfterSecond == secondNewOwner)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address differentOwner) public {
        require(differentOwner != newOwner, "differentOwner must differ");
        require(differentOwner != address(this), "test contract must not be differentOwner");

        c.transferOwnership(newOwner);

        address ownerAfterFirst = c.owner();

        bool revertedSecond;
        try c.transferOwnership(differentOwner) {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        address ownerAfterSecond = c.owner();

        assert(
            ownerAfterFirst == newOwner &&
            revertedSecond &&
            ownerAfterSecond == newOwner
        );
    }
}

